insert into article (slug, category_id, author_id, title, dek, body, read_minutes, hero_media_id, published_at, published, featured) values ('the-feds-last-mile-is-a-positioning-problem-not-a-data-problem', (select id from category where name='Macro & Rates' limit 1), (select id from author where name='Tomas Bek' limit 1), 'The Fed''s last mile is a positioning problem, not a data problem', 'Everyone agrees on the direction. Almost nobody agrees on the size — and that is where the pain trade lives.', $j$["The September meeting is the first in two years where the front end and the strategist consensus disagree by more than a single cut. That gap is not an information problem — the data is public and unusually clean. It is a positioning problem: the market has been paid to fade extremes since March, and fading extremes is now the crowded trade.","What matters for the next four weeks is less the print and more who has to move if the print is boring. Real money has duration on, fast money is short the front end, and both are sized as if the distribution is narrow. It is not.","Our read: own optionality around the meeting rather than a directional view. The cheapest expression is still in the curve, not in outright levels."]$j$::jsonb, 6, (select id from media_asset where url = 'uploads/Gemini_Generated_Image_udj4nuudj4nuudj4.png' limit 1), '2026-08-03T13:30:00Z', true, true);
insert into article (slug, category_id, author_id, title, dek, body, read_minutes, hero_media_id, published_at, published, featured) values ('a-13-handle-vix-does-not-mean-the-tails-are-cheap', (select id from category where name='Options & Volatility' limit 1), (select id from author where name='Renee Ash' limit 1), 'A 13-handle VIX does not mean the tails are cheap', 'Index vol is low because dispersion is high. Those are different trades and they are being priced as one.', $j$["Single-name implied vol has barely moved while index vol has bled for six weeks. That is textbook dispersion, and it is what makes the headline VIX number misleading for anyone selling premium on the index.","If you are short index vol here, you are short correlation, whether or not you meant to be. The position works until one sector stops moving independently — and semis are the obvious candidate.","Sizing rule we keep repeating on the show: half the notional you think the edge deserves, and write the exit down before the position is on."]$j$::jsonb, 5, (select id from media_asset where url = 'uploads/Gemini_Generated_Image_wo6oltwo6oltwo6o.png' limit 1), '2026-08-02T13:30:00Z', true, false);
insert into article (slug, category_id, author_id, title, dek, body, read_minutes, hero_media_id, published_at, published, featured) values ('breadth-has-been-telling-a-different-story-since-june', (select id from category where name='Technicals & Flow' limit 1), (select id from author where name='Ilya Grant' limit 1), 'Breadth has been telling a different story since June', 'The index is up. The median stock is not. Here is the level that decides which one is right.', $j$["Equal-weight has underperformed cap-weight for nine of the last eleven weeks. That is not automatically bearish — narrow tapes can run for months — but it does change what a break of 5,940 means.","Watch participation on any move above 6,010. If fewer than half the S&P names confirm, the breakout is a leadership event, not a market event, and it should be traded through the leaders rather than the index."]$j$::jsonb, 4, (select id from media_asset where url = 'uploads/Gemini_Generated_Image_mlj41hmlj41hmlj4.png' limit 1), '2026-08-01T13:30:00Z', true, false);
insert into article (slug, category_id, author_id, title, dek, body, read_minutes, hero_media_id, published_at, published, featured) values ('capex-disclosures-are-the-only-guidance-that-matters-this-quarter', (select id from category where name='Earnings' limit 1), (select id from author where name='Dana Whitfield' limit 1), 'Capex disclosures are the only guidance that matters this quarter', 'Forget the beat. The spend schedule is where the multiple gets decided.', $j$["Three of the four largest hyperscalers moved their capex language this quarter without moving the headline number. The buy side noticed; the tape took two sessions to.","For semis, the read-through is mechanical: capex commitments dated beyond eighteen months are being valued at roughly half the multiple of near-term orders. That spread is the trade.","The risk is that a single guidance walk-back re-rates the whole complex. Position accordingly — this is a group where the correlation goes to one on bad news."]$j$::jsonb, 7, (select id from media_asset where url = 'uploads/Gemini_Generated_Image_bsfmq5bsfmq5bsfm-fa91b74f.png' limit 1), '2026-07-31T13:30:00Z', true, false);
insert into article (slug, category_id, author_id, title, dek, body, read_minutes, hero_media_id, published_at, published, featured) values ('the-book-that-broke-me-was-the-one-i-understood-best', (select id from category where name='Interviews & Long Form' limit 1), (select id from author where name='Amara Reid' limit 1), '“The book that broke me was the one I understood best”', 'A prop desk head on risk limits, hiring, and the drawdown that changed how he sizes everything.', $j$["He has run the same desk for eleven years and has fired more traders for process than for P&L. The conversation kept returning to one idea: conviction is not a risk input.","On hiring: he no longer asks candidates for their best trade. He asks for the trade they held too long, and listens for whether the story has a number in it."]$j$::jsonb, 12, (select id from media_asset where url = 'uploads/Gemini_Generated_Image_jik0zpjik0zpjik0-ef37c215.png' limit 1), '2026-07-30T13:30:00Z', true, false);
insert into article (slug, category_id, author_id, title, dek, body, read_minutes, hero_media_id, published_at, published, featured) values ('yen-carry-is-rebuilding-quietly', (select id from category where name='Macro & Rates' limit 1), (select id from author where name='Lena Hoffmann' limit 1), 'Yen carry is rebuilding, quietly', 'The unwind is over. The funding trade is back on — with worse liquidity underneath it.', $j$["Positioning data suggests the carry trade has rebuilt roughly two thirds of what came off in the spring, but through a narrower set of counterparties.","That matters more than the size. The same notional in fewer hands means the next unwind is faster, and the gaps are wider. Hedge the gap, not the level."]$j$::jsonb, 5, (select id from media_asset where url = 'uploads/Gemini_Generated_Image_bsfmq5bsfmq5bsfm.png' limit 1), '2026-07-29T13:30:00Z', true, false);
insert into article (slug, category_id, author_id, title, dek, body, read_minutes, hero_media_id, published_at, published, featured) values ('the-last-hour-in-august-is-a-different-market', (select id from category where name='Technicals & Flow' limit 1), (select id from author where name='Ilya Grant' limit 1), 'The last hour in August is a different market', 'Thin books, heavier closes, and fills that do not look like your backtest.', $j$["Close auction share of daily volume has climbed for four straight Augusts. If your strategy assumes continuous liquidity, August is where the assumption quietly stops being true.","Practical fix: move execution earlier, size down into the final thirty minutes, and treat the auction print as information rather than a target."]$j$::jsonb, 4, (select id from media_asset where url = 'uploads/Gemini_Generated_Image_jik0zpjik0zpjik0.png' limit 1), '2026-07-28T13:30:00Z', true, false);
insert into article (slug, category_id, author_id, title, dek, body, read_minutes, hero_media_id, published_at, published, featured) values ('retails-downgrade-is-happening-in-the-mix-not-the-top-line', (select id from category where name='Earnings' limit 1), (select id from author where name='Marcus Oyelaran' limit 1), 'Retail''s downgrade is happening in the mix, not the top line', 'Traffic is fine. Ticket is fine. What people put in the basket is not.', $j$["Three consecutive quarters of mix shift toward private label and smaller pack sizes is not a promotion cycle. It is a consumer decision that shows up in margin before it shows up in revenue.","The names that have already guided margin down are, counterintuitively, the cleaner longs here. The risk sits with anyone still holding a full-year margin number set in January."]$j$::jsonb, 6, (select id from media_asset where url = 'uploads/Gemini_Generated_Image_udj4nuudj4nuudj4.png' limit 1), '2026-07-27T13:30:00Z', true, false);
