-- home layout blocks (derived from newest content)
  select 'featured', 'episode', e.id, (row_number() over (order by e.published_at desc nulls last))::int
  from episode e order by e.published_at desc nulls last limit 6;
  select 'most_watched', 'episode', e.id, (row_number() over (order by e.published_at desc nulls last))::int
  from episode e order by e.published_at desc nulls last offset 6 limit 5;
  select 'up_next', 'video', v.id, (row_number() over (order by v.published_at desc nulls last))::int
  from video v order by v.published_at desc nulls last limit 3;

